"use client"

import { useEffect, useMemo, useRef, useState } from "react"
import { motion, useInView, useReducedMotion } from "motion/react"

import { ChartCard } from "@/components/ui/chart-overlay"
import { parkBeside, squarify as squarifyBox } from "@/components/ui/market-heatmap-squarify"
import { cn } from "@/lib/utils"

/* Allocation Treemap, new through ssych-component (2026-09-29).
   What it is for: seeing how a book is split, where the area of a tile is the share of
   the book it holds.
   Read first: the largest tile, top left, the strongest ink.
   The pointer: pointing at a tile, or tabbing to it, turns it the accent, dims the rest
   and reads its share and its value in a card parked beside it (since 2026-10-02).
   Sketch: lab/AllocationTreemap. Kept from it: the holdings and their weights, the book,
   the squarified layout that measures its own box so tiles stay near square at any
   shape, the `height` prop for a plot band, the eased re-tiling when the weights change,
   and the readout (in the header until 2026-10-02, now in a card beside the tile).
   Rebuilt: the per-holding colour is dropped from the data (it was blue, green, amber and
   purple by position). Tiles are one ink at several strengths, strongest for the largest
   weight, and only the pointed tile takes var(--chart-1). The outlined, filled frame
   around the map and the text shadow are gone. Tiles are laid out largest first, which
   is what the squarifier needs to keep them near square.
   Formulas, all from `holdings` and `book`:
   · tile area = weight / sum of weights × area of the map
   · share     = weight / sum of weights × 100
   · value     = weight / sum of weights × book
   · strength  = the tile's rank by weight picks a step of STEPS, largest first
   Motion (2026-10-01): once the map first comes into view the tiles settle in largest first,
   a fade and 0.96 to full size, 40ms apart, done by about 700ms (it ran on mount, in 280ms).
   New weights or a new box re-tile in one 320ms glide, still by layout transforms. Reduced
   motion draws the end state and does not glide.
   2026-10-02 audit: the Treemap family now shares one look and one width with Market Heatmap,
   so the map is 460 wide in a 460 by 280 frame, tiles have a 6px corner with a 2px gap, and
   the squarifier is the family's shared one (market-heatmap-squarify). The readout line above
   the map, with its dot separators, is gone; the pointed tile reads in the shared ChartCard
   parked beside it (Share, Value), the same card the heatmap uses. The share printed on a
   tile is 10.5px at /60 and money is written with a capital K. */

const EASE = [0.16, 1, 0.3, 1] as const
const ACCENT = "var(--chart-1)"

export interface TreemapHolding {
  name: string
  /** any unit: weights are taken against their own sum */
  weight: number
}

export interface AllocationTreemapProps {
  holdings?: TreemapHolding[]
  /** dollars under management; a tile's value is its share of this */
  book?: number
  /** the map's name, read to assistive tech only */
  title?: string
  /** map height in px; left out, the map keeps the Treemap family's 460:280 frame (100:62 before 2026-10-02) */
  height?: number
  className?: string
}

const DEFAULT_BOOK = 128400

const DEFAULT_HOLDINGS: TreemapHolding[] = [
  { name: "AAPL", weight: 24.8 },
  { name: "MSFT", weight: 18.2 },
  { name: "NVDA", weight: 15.6 },
  { name: "AMZN", weight: 11.3 },
  { name: "GOOGL", weight: 9.1 },
  { name: "Other", weight: 8.4 },
  { name: "META", weight: 7.4 },
  { name: "TSLA", weight: 5.2 },
]

/** the ink of a tile by its rank, largest first; past the end tiles stay at the last step.
 *  Kept low so the name on the tile reads in the foreground in both themes. */
const STEPS = [32, 26, 21, 17, 14, 11, 9, 7]
const inkAt = (rank: number) => `color-mix(in srgb, var(--foreground) ${STEPS[Math.min(rank, STEPS.length - 1)]}%, transparent)`

/** the Treemap family's frame, the same as Market Heatmap's 460 × 280 */
const FRAME_W = 460
const FRAME_H = 280
const RATIO = FRAME_W / FRAME_H

/** tile geometry in percent of the box on both axes */
type Tile = TreemapHolding & { x: number; y: number; w: number; h: number; rank: number }

/** Squarified layout in a box `ratio` wide and 1 tall, so square means square on screen. */
function squarify(items: TreemapHolding[], ratio: number): Tile[] {
  return squarifyBox(items, (it) => it.weight, ratio, 1).map((t) => ({
    name: t.item.name,
    weight: t.item.weight,
    rank: t.rank,
    x: (t.x / ratio) * 100,
    y: t.y * 100,
    w: (t.w / ratio) * 100,
    h: t.h * 100,
  }))
}

/** the readout card: 132 wide, and its height from its fixed type (10px heading, two 11px rows) */
const CARD_W = 132
const CARD_H = 84

const usd = (v: number) => (Math.abs(v) >= 1000 ? `$${(v / 1000).toFixed(1)}K` : `$${v.toFixed(0)}`)

/**
 * Holdings as a treemap: the area of a tile is its share of the book, in one ink that is
 * strongest for the largest. Pointing at a tile turns it the accent and reads its share
 * and value in a card parked beside it.
 */
export function AllocationTreemap({ holdings = DEFAULT_HOLDINGS, book = DEFAULT_BOOK, title = "Allocation", height, className }: AllocationTreemapProps) {
  const reduced = useReducedMotion()
  const [hot, setHot] = useState<string | null>(null)

  /* the box measures itself, so the layout is made for the shape the tiles land in */
  const boxRef = useRef<HTMLDivElement>(null)
  const seen = useInView(boxRef, { once: true, amount: 0.3 })
  const entered = seen || !!reduced
  const [box, setBox] = useState<{ w: number; h: number } | null>(null)
  useEffect(() => {
    const el = boxRef.current
    if (!el || typeof ResizeObserver === "undefined") return
    const ro = new ResizeObserver(([e]) => {
      const { width, height: h } = e.contentRect
      if (width > 0 && h > 0) setBox((b) => (b && b.w === width && b.h === h ? b : { w: width, h }))
    })
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  const ratio = box ? box.w / box.h : RATIO
  const tiles = useMemo(() => squarify(holdings, ratio), [holdings, ratio])
  const total = tiles.reduce((s, t) => s + t.weight, 0) || 1
  const shareOf = (t: Tile) => (t.weight / total) * 100
  const shown = tiles.find((t) => t.name === hot) ?? null
  const largest = tiles[0]
  /* the card parks clear of the pointed tile, in px of the measured box */
  const bw = box?.w ?? FRAME_W
  const bh = box?.h ?? (height ?? FRAME_H)
  const park = shown ? parkBeside({ x: (shown.x / 100) * bw, y: (shown.y / 100) * bh, w: (shown.w / 100) * bw, h: (shown.h / 100) * bh }, CARD_W, CARD_H, bw, bh) : null

  return (
    <div className={cn("w-[460px] max-w-full tabular-nums", className)}>
      <div
        ref={boxRef}
        role="group"
        aria-label={`${title}, ${tiles.length} positions in a ${usd(book)} book${largest ? `. Largest: ${largest.name} ${shareOf(largest).toFixed(1)}%` : ""}`}
        className="relative w-full"
        style={height ? { height } : { aspectRatio: `${FRAME_W} / ${FRAME_H}` }}
        onPointerLeave={() => setHot(null)}
      >
        {tiles.map((t) => {
          const on = hot === t.name
          const dim = hot !== null && !on
          /* the label prints only where two lines of type and the padding fit */
          const big = box ? (t.w / 100) * box.w > 54 && (t.h / 100) * box.h > 40 : t.w > 15 && t.h > 13
          return (
            <motion.button
              key={t.name}
              type="button"
              aria-label={`${t.name} ${shareOf(t).toFixed(1)}%, ${usd((t.weight / total) * book)}`}
              onPointerEnter={() => setHot(t.name)}
              onFocus={() => setHot(t.name)}
              onBlur={() => setHot(null)}
              className="absolute outline-none"
              /* a board that moves its weights re-tiles in one 320ms glide, done by layout
                 transforms (never a left, top, width or height tween); still when they are fixed */
              layout={!reduced}
              style={{ left: `${t.x}%`, top: `${t.y}%`, width: `${t.w}%`, height: `${t.h}%` }}
              initial={reduced ? false : { opacity: 0, scale: 0.96 }}
              animate={entered ? { opacity: 1, scale: 1 } : { opacity: 0, scale: 0.96 }}
              transition={reduced ? { duration: 0 } : { duration: 0.4, ease: EASE, delay: t.rank * 0.04, layout: { duration: 0.32, ease: EASE } }}
            >
              <motion.span
                layout={!reduced}
                transition={{ layout: { duration: 0.32, ease: EASE } }}
                className="absolute inset-[1px] flex flex-col justify-end p-2 text-left"
                style={{
                  borderRadius: 6,
                  background: on ? ACCENT : inkAt(t.rank),
                  opacity: dim ? 0.4 : 1,
                  transition: reduced ? "none" : "background-color 160ms, opacity 160ms",
                }}
              >
                {big && (
                  <>
                    <span className="text-[11px] font-medium leading-none text-foreground/90">{t.name}</span>
                    <span className={cn("mt-1 text-[10.5px] leading-none", on ? "text-foreground/90" : "text-foreground/60")}>{shareOf(t).toFixed(1)}%</span>
                  </>
                )}
              </motion.span>
            </motion.button>
          )
        })}

        {/* the pointed tile reads here; ChartCard sits 12px right of x */}
        <ChartCard
          open={!!shown && !!park}
          x={(park?.left ?? 0) - 12}
          y={park?.top ?? 0}
          width={CARD_W}
          heading={shown ? <span className="font-medium text-foreground/90">{shown.name}</span> : null}
          rows={
            shown
              ? [
                  { label: "Share", value: `${shareOf(shown).toFixed(1)}%` },
                  { label: "Value", value: usd((shown.weight / total) * book) },
                ]
              : []
          }
        />
      </div>
    </div>
  )
}

"use client"

import { type ReactNode } from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

/* Chart overlay: the two parts every library chart reads a point with (2026-10-02). They
   came out of Candlestick, Volume Profile, the trading terminal and Price Scrubber, which
   had each drawn their own; this is the one copy. Shipped beside the charts that use it.

   AxisTag   the outlined tag on the value axis: the pointed value in its hue, or a named
             reference (POC, last close) in ink. A pill 16px high, 8.5px figures.
   ChartCard the card laid over the chart beside the cursor: a heading row (a time or a
             range) at /60, then label and value rows (labels 10px /60, values 11px /90),
             the one signed figure in its hue. It glides between points on a spring, fades
             in from 0.97 and out in 120ms, and flips to the cursor's left when told to.

   2026-10-02: the card looked out of place over the charts, so it now wears the library
   popover, the same as the sidebar's hover card: a hairline border at 8%, radius 12, the
   6% foreground mix and the popover shadow with no inset highlight (spec 14.6). */

const EASE = [0.16, 1, 0.3, 1] as const
const GLIDE = { type: "spring", stiffness: 520, damping: 40 } as const

/** the outlined tag on a chart's value axis, centred on `y` */
export function AxisTag({
  x,
  y,
  width,
  color = "var(--foreground)",
  strong = true,
  hidden = false,
  children,
}: {
  /** the tag's left edge, in the chart's own units */
  x: number
  /** the value's line; the tag is centred on it */
  y: number
  width: number
  /** stroke and figure; ink for a named reference, the series hue for the pointed value */
  color?: string
  /** a quieter tag (a secondary reference) drops the weight and the stroke */
  strong?: boolean
  /** fades the tag out, for when the pointed value sits on it */
  hidden?: boolean
  children: ReactNode
}) {
  return (
    <g transform={`translate(${x}, ${y - 8})`} pointerEvents="none" style={{ opacity: hidden ? 0 : 1, transition: "opacity 150ms" }}>
      <rect width={width} height={16} rx={8} fill="var(--background)" stroke={color} strokeOpacity={strong ? 0.6 : 0.2} />
      <text x={width / 2} y={11} textAnchor="middle" fontSize={8.5} fontWeight={strong ? 600 : 500} fill={color} fillOpacity={strong ? 1 : 0.65}>
        {children}
      </text>
    </g>
  )
}

export interface ChartCardRow {
  label: string
  value: ReactNode
  /** only the one signed figure carries a hue */
  color?: string
}

/** the readout card over a chart; place it inside a `relative` box that holds the svg */
export function ChartCard({
  open,
  x,
  y = 4,
  flip = false,
  width = 148,
  heading,
  rows,
  footer,
}: {
  open: boolean
  /** the cursor's x inside the box: px, or a percentage string for a chart drawn to a viewBox */
  x: number | string
  /** the card's top inside the box, px */
  y?: number
  /** put the card on the cursor's left (past ~60% of the plot) */
  flip?: boolean
  width?: number
  heading: ReactNode
  rows: ChartCardRow[]
  /** a closing line under the rows, such as where the point sits */
  footer?: ReactNode
}) {
  const reduced = useReducedMotion()
  return (
    <AnimatePresence>
      {open && (
        <motion.div
          key="chart-card"
          role="status"
          className="pointer-events-none absolute z-10"
          initial={{ left: x, top: y, opacity: 0 }}
          animate={{ left: x, top: y, opacity: 1 }}
          exit={{ opacity: 0, transition: { duration: 0.12 } }}
          transition={reduced ? { duration: 0 } : { left: GLIDE, top: GLIDE, opacity: { duration: 0.15 } }}
        >
          <motion.div
            className="rounded-[12px] border border-foreground/[0.08] px-3 py-2.5"
            style={{
              width,
              translate: flip ? "calc(-100% - 12px) 0" : "12px 0",
              transition: reduced ? undefined : "translate 200ms cubic-bezier(0.16, 1, 0.3, 1)",
              background: "var(--tip-fill, color-mix(in srgb, var(--foreground) 6%, var(--background)))",
              boxShadow: "0 8px 24px var(--card-shadow, rgba(0,0,0,calc(0.35 * var(--shadow-k, 1))))",
            }}
            initial={reduced ? false : { scale: 0.97 }}
            animate={{ scale: 1 }}
            transition={{ duration: 0.15, ease: EASE }}
          >
            <div className="text-[10px] text-foreground/60">{heading}</div>
            <div className="mt-1.5 flex flex-col gap-1">
              {rows.map((r) => (
                <div key={r.label} className="flex items-center justify-between gap-3">
                  <span className="text-[10px] text-foreground/60">{r.label}</span>
                  <span className="text-[11px] text-foreground/90" style={r.color ? { color: r.color } : undefined}>
                    {r.value}
                  </span>
                </div>
              ))}
            </div>
            {footer && <div className="mt-1.5 text-[10px]">{footer}</div>}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

/* Squarify: the one squarified treemap layout the Treemap family shares (2026-10-02 audit).
   Market Heatmap and Allocation Treemap each carried their own copy of the same algorithm;
   this is that algorithm once, with the rule both use to park their readout card clear of the
   pointed tile (parkBeside). Ships beside both through the registry's helper bundling.

   Formula: items are sorted largest first and zero or negative sizes are dropped; each
   item's area = size / sum of sizes × (w × h). Rows are filled along the shorter side of
   the box that is left, and an item joins the row while it does not make the row's worst
   aspect ratio worse (Bruls, Huizing and van Wijk). Output is in the units of w and h. */

export interface SquarifiedTile<T> {
  x: number
  y: number
  w: number
  h: number
  item: T
  /** the item's rank by size, largest first (0 = largest) */
  rank: number
}

export function squarify<T>(items: T[], size: (item: T) => number, w: number, h: number): SquarifiedTile<T>[] {
  const sorted = items.filter((it) => size(it) > 0).sort((a, b) => size(b) - size(a))
  const total = sorted.reduce((s, it) => s + size(it), 0) || 1
  const queue = sorted.map((item, rank) => ({ item, rank, area: (size(item) / total) * w * h }))
  const sum = (row: { area: number }[]) => row.reduce((s, r) => s + r.area, 0)
  const worst = (row: { area: number }[], side: number) => {
    const s = sum(row)
    const areas = row.map((r) => r.area)
    return Math.max((side * side * Math.max(...areas)) / (s * s), (s * s) / (side * side * Math.min(...areas)))
  }

  const out: SquarifiedTile<T>[] = []
  let box = { x: 0, y: 0, w, h }
  let i = 0
  while (i < queue.length) {
    const side = Math.min(box.w, box.h)
    const row = [queue[i]]
    let k = i + 1
    while (k < queue.length && worst([...row, queue[k]], side) <= worst(row, side)) {
      row.push(queue[k])
      k += 1
    }
    const depth = sum(row) / side
    let run = 0
    for (const r of row) {
      const len = r.area / depth
      const tile = box.w >= box.h ? { x: box.x, y: box.y + run, w: depth, h: len } : { x: box.x + run, y: box.y, w: len, h: depth }
      out.push({ ...tile, item: r.item, rank: r.rank })
      run += len
    }
    box = box.w >= box.h ? { x: box.x + depth, y: box.y, w: box.w - depth, h: box.h } : { x: box.x, y: box.y + depth, w: box.w, h: box.h - depth }
    i = k
  }
  return out
}

/** Where a readout card of `cw` × `ch` parks beside a tile inside a `bw` × `bh` box, all in px:
 *  above the tile, else below, else to its right, else to its left, else the far corner;
 *  always clamped inside the box, so the card never covers the tile it reads. */
export function parkBeside(
  t: { x: number; y: number; w: number; h: number },
  cw: number,
  ch: number,
  bw: number,
  bh: number,
  gap = 8,
): { left: number; top: number } {
  const cx = Math.max(0, Math.min(bw - cw, t.x + t.w / 2 - cw / 2))
  const cy = Math.max(0, Math.min(bh - ch, t.y + t.h / 2 - ch / 2))
  const above = t.y - gap - ch
  if (above >= 0) return { left: cx, top: above }
  const below = t.y + t.h + gap
  if (below + ch <= bh) return { left: cx, top: below }
  const right = t.x + t.w + gap
  if (right + cw <= bw) return { left: right, top: cy }
  const left = t.x - gap - cw
  if (left >= 0) return { left, top: cy }
  return { left: t.x < bw / 2 ? bw - cw : 0, top: t.y < bh / 2 ? bh - ch : 0 }
}
